import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      // کل JSON دریافتی از API
      userData: null,

      // لیست قابل نمایش
      technicians: [],

      searchTerm: "",

      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",

      loading: true,
      authenticated: false,
    };

    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.handleSearch = this.handleSearch.bind(this);

    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);

    this.handleDelete = this.handleDelete.bind(this);
    this.handleToggleStatus = this.handleToggleStatus.bind(this);
    this.handleDetails = this.handleDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getTechnicians();
      }
    );
  }

  // =========================
  // دریافت کاربران
  // =========================

  getTechnicians() {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/users`, {
      method: "GET",

      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("USERS API:", data);

        // کل JSON داخل state
        this.setState(
          {
            userData: data,
            loading: false,
          },
          () => {
            // بعد از ذخیره JSON
            this.handleSearch();
          }
        );
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          userData: null,
          technicians: [],
          loading: false,
        });
      });
  }

  // =========================
  // تبدیل کاربران API
  // =========================

  getUserList() {
    const { userData } = this.state;

    if (!userData) {
      return [];
    }

    if (Array.isArray(userData.users)) {
      return userData.users;
    }

    /*
     * اگر خود response آرایه باشد
     */
    if (Array.isArray(userData)) {
      return userData;
    }

    return [];
  }

  // =========================
  // جستجو
  // =========================

  handleSearchChange(e) {
    const value = e.target.value;

    this.setState(
      {
        searchTerm: value,
      },
      () => {
        this.handleSearch();
      }
    );
  }

  handleSearch() {
    const { searchTerm } = this.state;

    const users = this.getUserList();

    const search = searchTerm.trim().toLowerCase();

    let result = users;

    if (search !== "") {
      result = users.filter((user) => {
        const name = `${user.name || ""} ${user.family || ""}`
          .trim()
          .toLowerCase();

        return name.includes(search);
      });
    }

    const technicians = result.map((user) => ({
      ...user,

      id: user.id,

      name: `${user.name || ""} ${user.family || ""}`.trim(),

      status: Number(user.active) === 1 ? "free" : "blocked",

      avatar: user.image
        ? `https://iranaserviceapp.ir/test/${user.image}`
        : `https://ui-avatars.com/api/?name=${encodeURIComponent(
            `${user.name || ""} ${user.family || ""}`
          )}&background=e9ecef&color=495057`,
    }));

    this.setState({
      technicians: technicians,
    });
  }

  // =========================
  // فیلتر
  // =========================

  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  applyFilter() {
    this.closeFilter();

    // فعلاً فیلترها API نشده‌اند
    this.handleSearch();
  }

  // =========================
  // حذف تعمیرکار
  // =========================

  handleDelete(id) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/delete`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("DELETE USER:", data);

        if (String(data.status) === "1") {
          // حذف از JSON اصلی
          this.setState(
            (prev) => {
              if (!prev.userData) {
                return null;
              }

              const users = prev.userData.users || [];

              return {
                userData: {
                  ...prev.userData,
                  users: users.filter((user) => user.id !== id),
                },
              };
            },
            () => {
              this.handleSearch();
            }
          );
        }
      })
      .catch((error) => {
        console.error("DELETE USER ERROR:", error);
      });
  }

  // =========================
  // فعال / مسدود
  // =========================

  handleToggleStatus(id, currentStatus) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/active`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("ACTIVE USER:", data);

        if (String(data.status) === "1") {
          this.setState(
            (prev) => {
              if (!prev.userData) {
                return null;
              }

              const users = prev.userData.users || [];

              return {
                userData: {
                  ...prev.userData,

                  users: users.map((user) =>
                    user.id === id
                      ? {
                          ...user,
                          active: Number(user.active) === 1 ? 0 : 1,
                        }
                      : user
                  ),
                },
              };
            },
            () => {
              this.handleSearch();
            }
          );
        }
      })
      .catch((error) => {
        console.error("ACTIVE USER ERROR:", error);
      });
  }

  // =========================
  // جزئیات
  // =========================

  handleDetails(id) {
    console.log("جزئیات تعمیرکار:", id);
  }

  // =========================
  // Render
  // =========================

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      technicians,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت تعمیرکاران...
        </div>
      );
    }

    return (
      <div dir="rtl">
        <div className="container px-3 pt-3">

          {/* جستجو */}
          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">
            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />

            <FaSearch
              className="text-secondary"
              size={16}
            />
          </div>

          {/* فیلتر */}
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.openFilter}
              className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
            >
              <span>فیلتر</span>

              <FaFilter
                className="text-secondary"
                size={14}
              />
            </button>
          </div>

          {/* عنوان */}
          <div className="bg-light text-center rounded-3 py-3 mb-1">
            <span className="text-primary fw-semibold">
              تعمیرکاران
            </span>
          </div>

          {/* لیست */}
          <div>
            {technicians.map((technician) => (
              <TechnicianItem
                key={technician.id}
                technician={technician}
                onDelete={this.handleDelete}
                onToggleStatus={this.handleToggleStatus}
                onDetails={this.handleDetails}
              />
            ))}

            {technicians.length === 0 && (
              <div className="text-center text-muted py-5">
                موردی یافت نشد
              </div>
            )}
          </div>
        </div>

        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}
          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}
          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
            })
          }
          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }
          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />
      </div>
    );
  }
}

export default TechniciansPage;
